import React, { useState, useContext } from "react";
import { AuthContext } from "../../../Context/AuthContext"; // đường dẫn tuỳ vị trí file
import './ModalLogin.css';

import { useNavigate } from 'react-router-dom';
const ModalLogin = ({ show, handleClose }) => {
    const { login } = useContext(AuthContext);
    const [formModalLogin, setFormModalLogin] = useState({
        accountname: "",
        password: "",
    });

    const navigate = useNavigate();
    // if show = True thì !show = false mà false thì bỏ qua . nếu show = false thì !show = true . điều kiện đúng trả về null 
    if (!show) return null;

    const handleRegisterClick = () => {
        handleClose(); // đóng modal
        navigate('/register'); // chuyển sang trang đăng ký
    };

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) {
            handleClose();
        }
    };
    const handleSubmitLogin = async (e) => {
        e.preventDefault(); // Ngăn chặn hành vi mặc định của form (tải lại trang)
        // Gọi API đăng nhập ở đây
        if (!formModalLogin.accountname || !formModalLogin.password) {
            alert("Vui lòng nhập đầy đủ thông tin");
            return;
        }
        try {
            const data = await login(formModalLogin);
            alert("Login successful!");
            console.log("Login data:", data);
            setFormModalLogin({
                accountname: "",
                password: "",
            });
            handleClose(); // Đóng modal sau khi đăng nhập thành công
            navigate('/'); // Chuyển hướng sang trang chủ (hoặc trang bạn muốn)
        } catch (error) {
            console.error("Login failed:", error);
            alert("Login failed:" + (error.response?.data?.message || error.message));
        }
    };

    return (
        <>
            {/* Modal Backdrop */}
            <div className="modal-backdrop-custom" onClick={handleBackdropClick} style={{ backdropFilter: 'blur(5px)' }}>{/* Modal Backdrop sử dụng để làm mờ phần còn lại của trang */}
                <div className="modal-dialog modal-lg modal-dialog-centered animate__animated animate__fadeInUp"> {/* Modal dialog phần hộp thoại chính bên trong modal để bao bọc content   modal-lg : size modal  */}
                    <div className="modal-content border-0 rounded-4 overflow-hidden shadow-lg" style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}>
                        <div className="modal-body p-0">
                            <div className="row g-0">
                                {/* Left Side - Gradient */}
                                <div className="col-md-5 modal-left-gradient d-flex flex-column justify-content-center align-items-center text-white p-5" style={{ background: 'linear-gradient(135deg, #ff9a9e 0%, #fecfef 50%, #fecfef 100%)' }}>
                                    <div className="text-center">
                                        <h2 className="fw-bold mb-3 display-6" style={{ textShadow: '2px 2px 4px rgba(0,0,0,0.3)' }}>ĐĂNG KÝ</h2>
                                        <p className="mb-4 fs-6">Bạn chưa có tài khoản, đăng ký ngay!</p>
                                        <button className="btn btn-outline-light btn-lg px-4 py-2 rounded-3 fw-semibold border-2 shadow-sm" onClick={handleRegisterClick} style={{ transition: 'all 0.3s ease' }}>
                                            ĐĂNG KÝ TÀI KHOẢN MỚI
                                        </button>
                                    </div>
                                </div>

                                {/* Right Side - Login Form */}
                                <div className="col-md-7 p-5 position-relative" style={{ background: 'linear-gradient(to bottom, #ffffff 0%, #f8f9fa 100%)' }}>
                                    {/* Close Button */}
                                    <button
                                        type="button"
                                        className="btn-close position-absolute top-0 end-0 m-3"
                                        onClick={handleClose}
                                        style={{ filter: 'invert(1)' }}
                                    ></button>

                                    <div className="login-form-container">
                                        <h3 className="fw-bold mb-4 text-dark" style={{ color: '#333' }}>ĐĂNG NHẬP</h3>

                                        <form onSubmit={handleSubmitLogin}>
                                            {/* Username/Email Input */}
                                            <div className="mb-3">
                                                <label className="form-label fw-semibold text-dark mb-2">
                                                    Tên tài khoản *
                                                </label>
                                                <input
                                                    type="text"
                                                    className="form-control form-control-lg bg-light border-0 rounded-3 px-3 shadow-sm"
                                                    placeholder="Nhập tên tài khoản !"
                                                    style={{ backgroundColor: '#f8f9fa', transition: 'box-shadow 0.3s ease' }}
                                                    name="accountname"
                                                    autoComplete="accountname"
                                                    value={formModalLogin.accountname}
                                                    onChange={(e) => setFormModalLogin({ ...formModalLogin, accountname: e.target.value })}
                                                />
                                            </div>

                                            {/* Password Input */}
                                            <div className="mb-3">
                                                <label className="form-label fw-semibold text-dark mb-2">
                                                    Mật khẩu *
                                                </label>
                                                <input
                                                    type="password"
                                                    className="form-control form-control-lg bg-light border-0 rounded-3 px-3 shadow-sm"
                                                    placeholder="••••••••"
                                                    style={{ backgroundColor: '#f8f9fa', transition: 'box-shadow 0.3s ease' }}
                                                    name="password"
                                                    autoComplete="current-password"
                                                    value={formModalLogin.password}
                                                    onChange={(e) => setFormModalLogin({ ...formModalLogin, password: e.target.value })}
                                                />
                                            </div>

                                            {/* Remember Password Checkbox */}
                                            <div className="form-check mb-3">
                                                <input
                                                    className="form-check-input"
                                                    type="checkbox"
                                                    id="rememberPassword"
                                                />
                                                <label className="form-check-label text-dark" htmlFor="rememberPassword">
                                                    Ghi nhớ mật khẩu
                                                </label>
                                            </div>

                                            {/* Login Button */}
                                            <button
                                                type="submit"
                                                className="btn btn-warning btn-lg w-100 fw-bold rounded-3 mb-3 text-white shadow-sm"
                                                style={{
                                                    backgroundColor: '#ff6b35',
                                                    borderColor: '#ff6b35',
                                                    padding: '12px',
                                                    transition: 'all 0.3s ease'
                                                }}
                                            >
                                                ĐĂNG NHẬP
                                            </button>

                                            {/* Forgot Password Link */}
                                            <div className="text-center mb-4">
                                                <a href="/forgot-password" className="text-decoration-none text-muted" style={{ color: '#6c757d' }}>
                                                    Quên mật khẩu?
                                                </a>
                                            </div>
                                        </form>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Social Login Footer */}
                        <div className="modal-footer bg-white border-0 pt-0 pb-4">
                            <div className="container-fluid">
                                <div className="d-flex justify-content-center gap-3">
                                    <button
                                        type="button"
                                        className="btn btn-primary fw-semibold rounded-pill d-flex align-items-center justify-content-center shadow-sm px-4 py-2"
                                        style={{
                                            backgroundColor: '#4267B2',
                                            borderColor: '#4267B2',
                                            transition: 'all 0.3s ease'
                                        }}
                                    >
                                        <i className="fab fa-facebook-f me-2"></i>
                                        ĐĂNG NHẬP BẰNG FACEBOOK
                                    </button>
                                    <button
                                        type="button"
                                        className="btn btn-danger fw-semibold rounded-pill d-flex align-items-center justify-content-center shadow-sm px-4 py-2"
                                        style={{
                                            backgroundColor: '#db4437',
                                            borderColor: '#db4437',
                                            transition: 'all 0.3s ease'
                                        }}
                                    >
                                        <i className="fab fa-google me-2"></i>
                                        ĐĂNG NHẬP BẰNG GOOGLE
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};

export default ModalLogin;
